        "answer": "Comprehensive examination: Howard Gardner's conceptualization (Frames of Mind, 1983); Critiquing single\nunitary IQ; Eight distinct intelligences: (1) Linguistic (poets, writers); (2) Logical-Mathematical (scientists,\nmathematicians); (3) Spatial (pilots, sculptors, architects); (4) Musical (composers, singers); (5) Bodily-Kinaesthetic\n(athletes, dancers, surgeons); (6) Interpersonal (counselors, politicians); (7) Intrapersonal (philosophers, spiritual\nleaders); (8) Naturalistic (botanists, wildlife conservationists).\nStep-by-Step Marking Scheme (1 Mark theoretical background + 5 Marks detailed explanation of the eight intelligences\nwith vocational examples):\n• 1. Theoretical Rationale [1 Mark]:\n- Howard Gardner (1983) challenged the unitary view of intelligence, arguing that intelligence consists of distinct,\nautonomous cognitive modules that operate relatively independently.\n• 2. Eight Multiple Intelligences [5 Marks - roughly 0.6 Mark each]:\n- Linguistic: Sensitivity to language structure, sounds, and rhythms (e.g. poets like Rabindranath Tagore, authors, orators).\n- Logical-Mathematical: Capacity to discern logical/numerical patterns and handle abstract chains of reasoning (e.g.\nscientists, mathematicians like Ramanujan).\n- Spatial: Ability to form mental images and navigate 3D spatial environments (e.g. sailors, pilots, architects, sculptors).\n- Musical: Sensitivity to rhythm, pitch, timbre, and musical forms (e.g. composers, instrumentalists, vocalists).\n- Bodily-Kinaesthetic: Skill in using one's body for expression or goal-directed tasks (e.g. dancers, athletes, surgeons).\n- Interpersonal: Ability to perceive and respond to the moods, motivations, and desires of others (e.g. psychotherapists,\ndiplomats, teachers).\n- Intrapersonal: Knowledge of one's own internal strengths, vulnerabilities, and emotions (e.g. philosophers, spiritual\nleaders).\n- Naturalistic: Sensitivity to features of the natural world, plants, and animals (e.g. botanists, wildlife biologists, farmers).",
