        "tag": "CBSE 2024 - 4/6 Marks",
        "question": "Examine the 'PASS Model of Intelligence' proposed by J.P. Das, Jack Naglieri, and J.R. Kirby. Detail the functioning of Planning,\nAttention-Arousal, Simultaneous processing, and Successive processing, and describe the Cognitive Assessment System (CAS).\n[6 Marks]",
        "answer": "Detailed examination: Neuropsychological basis (Alexander Luria's three functional units); (1) Attention-Arousal\n(optimal arousal, reticular activating system, focusing attention); (2) Simultaneous Processing (integrating stimuli\ninto spatial patterns/relations, e.g. Raven's matrices); (3) Successive Processing (serial recall, temporal ordering,\ne.g. digit span); (4) Planning (executive decision making, goal setting, monitoring); Cognitive Assessment System\n(CAS battery for ages 5-18).",
        "explanation": "Step-by-Step Marking Scheme (1 Mark neuropsychological foundations + 4 Marks PASS components + 1 Mark CAS battery):\n• 1. Neuropsychological Foundations [1 Mark]:\n- Formulated by J.P. Das, Jack Naglieri, and J.R. Kirby (1994) based on Alexander Luria's three functional brain units,\nviewing intellectual activity as the dynamic interaction of distinct functional systems.\n• 2. Four PASS Components [4 Marks - 1 Mark each]:\n- Attention-Arousal: Arousal provides the physiological alertness needed to focus on relevant stimuli while inhibiting\ndistractors (governed by the brainstem and reticular formation).\n- Simultaneous Processing: Integrates diverse stimuli into a coherent pattern or spatial configuration where relationships\nbetween parts are perceived at once (e.g. Raven's Progressive Matrices).\n- Successive Processing: Organizes stimuli in a specific temporal sequence where each element leads linearly to the next\n(e.g. serial digit recall, learning multiplication tables).\n- Planning: The executive function; involves setting goals, choosing strategies, monitoring execution, and modifying\napproaches when needed (governed by the prefrontal cortex).\n• 3. Cognitive Assessment System (CAS) [1 Mark]:\n- A standardized diagnostic battery developed by Das and Naglieri (for ages 5-18) that assesses the four PASS processes\nto diagnose learning disabilities and cognitive profiles."
