        "tag": "CBSE 2023 - 4/6 Marks",
        "question": "Discuss the 'Nature versus Nurture' controversy in the development of intelligence. Review empirical evidence from twin\nstudies, adoption studies, and environmental enrichment programs. [6 Marks]",
        "answer": "Comprehensive review: Interactionist perspective; Evidence for Nature (Genetics): Monozygotic twins reared\ntogether (r=0.90), MZ twins reared apart (r=0.72), Dizygotic twins (r=0.60), Siblings (r=0.50); Evidence for Nurture\n(Environment): Adoption studies, Flynn effect, early childhood enrichment (Head Start), nutrition, schooling;\nReaction Range concept (genetics sets limits, environment determines position).\nStep-by-Step Marking Scheme (2 Marks genetic evidence + 2 Marks environmental evidence + 2 Marks reaction range &\ninteractionist synthesis):\n• 1. Evidence for Genetic Influences (Nature) [2 Marks]:\n- Twin Studies: Identical (monozygotic) twins reared together have a correlation of r ≈0.90 in IQ; even when separated at\nbirth and reared in different environments, they show r ≈0.72.\n- Fraternal (dizygotic) twins show lower concordance (r ≈0.60), and biological siblings show r ≈0.50, demonstrating that\ngenetic relatedness correlates with intellectual similarity.\n• 2. Evidence for Environmental Influences (Nurture) [2 Marks]:\n- Adoption Studies: Adopted children often show an increase in IQ when placed in stimulating, high-socioeconomic\nhomes.\n- Environmental Deprivation & Enrichment: Children raised in under-resourced institutions show lower intellectual\ndevelopment, while early interventions (e.g. Head Start) can yield cognitive gains.\n- Flynn Effect: Generational increases in average IQ scores over the 20th century reflect improvements in education,\nhealthcare, and nutrition rather than genetic shifts.\n• 3. The Reaction Range Synthesis [2 Marks]:\n- Psychologists conclude that intelligence results from an interaction of nature and nurture.\n- Heredity establishes a biological 'reaction range' (upper and lower boundaries), while environmental factors determine\nwhere an individual falls within that range.",
