        "answer": "Comparative exposition: (1) Western concept of technological intelligence: Focus on individual achievement,\ncognitive speed, abstraction, categorization, performance, analytical skill; (2) Indian concept of integral\nintelligence (Buddhi): Contextual, holistic, social responsibility, ethical grounding; (3) Four competencies of\nBuddhi: Cognitive, Social, Emotional, Entrepreneurial; Comparative synthesis.",
        "explanation": "Step-by-Step Marking Scheme (2 Marks Western model + 2 Marks Indian model + 2 Marks four competencies of Buddhi):\n• 1. Western Technological Intelligence [2 Marks]:\n- Focuses on individualistic cognitive skills: abstract reasoning, generalization, speed of processing, analysis, and rule-\nbased problem-solving.\n- Prioritizes personal autonomy, efficiency, and individual competitive success in technologically advanced societies.\n• 2. Indian Integral Intelligence (*Buddhi*) [2 Marks]:\n- Takes a holistic and contextual perspective, viewing intelligence as embedded in social relations, environmental\nharmony, and moral duty (*dharma*).\n- Emphasizes connecting the self with others and the natural environment, balancing cognitive achievement with\nemotional control.\n• 3. Four Core Competencies of Buddhi (J.P. Das) [2 Marks]:\n- Cognitive Competence: Contextual sensitivity, understanding, and discrimination.\n- Social Competence: Respect for social order, commitment to community, cooperation, and fulfilling interpersonal\nobligations.\n- Emotional Competence: Self-regulation, emotional balance, honesty, and ethical conduct.\n\n- Entrepreneurial Competence: Perseverance, persistence, patience, and goal-directed work."
