        "type": "LA",
        "tag": "CBSE 2022 - 4/6 Marks",
        "question": "What is 'Assessment'? Describe the five major psychological attributes assessed in psychology (Intelligence, Aptitude, Interest,\nPersonality, Values) and explain three formal assessment methods. [6 Marks]",
        "answer": "Detailed examination: Definition of Assessment (formal measurement of psychological attributes using\nstandardized methods); Five attributes: (1) Intelligence; (2) Aptitude; (3) Interest; (4) Personality; (5) Values;\nThree assessment methods: Psychological Test (objective, standardized), Interview, Case Study, Observation.\nStep-by-Step Marking Scheme (1 Mark definition + 2.5 Marks five psychological attributes + 2.5 Marks assessment\nmethods):\n• 1. Definition of Assessment [1 Mark]:\n- Assessment is the systematic evaluation of psychological attributes through standardized tests, structured interviews,\nand empirical observation to understand and predict human behavior.\n• 2. Five Key Psychological Attributes [2.5 Marks - 0.5 Mark each]:\n- Intelligence: The global capacity to understand the world, think rationally, and utilize resources effectively.\n- Aptitude: An individual's underlying potential to acquire specific skills following training.\n- Interest: An individual's enduring preference to engage in particular activities or fields.\n- Personality: The relatively stable, enduring pattern of traits that characterizes how an individual thinks, feels, and\nbehaves.\n- Values: Enduring beliefs regarding desirable modes of conduct or life goals (e.g. honesty, equality).\n• 3. Formal Assessment Methods [2.5 Marks]:\n- Psychological Tests: Objective, standardized instruments used to measure cognitive or behavioral traits (e.g. IQ tests,\npersonality questionnaires).\n- Interview: A purposeful, face-to-face dialogue between an interviewer and respondent to gather detailed personal\ninformation.\n- Case Study: An in-depth investigation of an individual's psychological history, developmental milestones, and\npsychosocial functioning.",
        "explanation": ""
