        "type": "LA",
        "tag": "CBSE 2021 - 4/6 Marks",
        "question": "Analyze the relationship between 'Creativity' and 'Intelligence'. Discuss whether high intelligence guarantees high creativity,\nthe threshold hypothesis, and compare tests of intelligence with tests of creativity. [6 Marks]",
        "answer": "Analytical exposition: Historical assumptions (Terman's gifted study); The Threshold Hypothesis (positive\ncorrelation at lower IQs, but beyond IQ ~115-120, correlation becomes weak); Divergent vs Convergent thinking;\nDifferences between IQ tests and Creativity tests: Open-ended vs single correct answer, speed vs novelty, scoring\ncriteria (fluency, flexibility, originality, elaboration).\nStep-by-Step Marking Scheme (2 Marks threshold hypothesis & empirical relationship + 2 Marks divergent vs convergent\nthinking + 2 Marks comparison of test characteristics):\n• 1. Empirical Relationship & The Threshold Hypothesis [2 Marks]:\n- Early studies assumed high IQ was identical to creativity, but Lewis Terman's longitudinal research found that many\nindividuals with very high IQs did not show exceptional creative output.\n- The 'Threshold Hypothesis' suggests that a baseline level of intelligence (around average to above-average, IQ\n~115–120) is helpful for creative work, but beyond that threshold, higher IQ scores do not guarantee higher creativity.\n• 2. Convergent vs Divergent Thinking [2 Marks]:\n- Intelligence tests evaluate convergent thinking, which requires focusing on a single correct answer through logic and\nrule-following.\n- Creativity relies primarily on divergent thinking, which involves generating a wide range of varied, original, and open-\nended ideas.\n\n• 3. Differences Between Intelligence and Creativity Tests [2 Marks]:\n- Structure: Intelligence tests use closed-ended questions with right/wrong answers; creativity tests use open-ended\nprompts (e.g. alternate uses for a brick).\n- Scoring Dimensions: Creativity tests evaluate responses on fluency (number of ideas), flexibility (variety of categories),\noriginality (statistical rarity), and elaboration (level of detail).",
