        "question": "Examine the classification and characteristics of 'Intellectual Deficiency' (Mental Retardation) and 'Intellectual Giftedness'. How\ncan educational curricula be adapted for both categories? [6 Marks]",
        "answer": "Detailed comparative examination: (1) Intellectual Deficiency (AAMR definition: IQ < 70, adaptive skill deficits,\nonset before 18; Mild, Moderate, Severe, Profound; Curriculum adaptations: Life skills, vocational training, task\nanalysis, positive reinforcement); (2) Intellectual Giftedness (IQ > 130, rapid processing, high curiosity, intrinsic\ndrive; Curriculum adaptations: Accelerated grade promotion, enrichment programs, independent research\nprojects).\nStep-by-Step Marking Scheme (2 Marks Intellectual Deficiency + 2 Marks Intellectual Giftedness + 2 Marks curricular\nadaptations for both):\n• 1. Intellectual Deficiency [2 Marks]:\n- Defined by an IQ score below 70, significant deficits in adaptive behaviors (communication, self-care, social skills), and\nonset before age 18.\n- Classified into four levels: Mild (IQ 55–69), Moderate (IQ 40–54), Severe (IQ 25–39), and Profound (IQ below 25).\n• 2. Intellectual Giftedness [2 Marks]:\n- Defined as exceptional general intellectual ability, typically indicated by an IQ score of 130 or higher.\n- Key characteristics include rapid information processing, advanced metacognition, high intrinsic motivation, intense\ncuriosity, and independent problem-solving.\n• 3. Curricular Adaptations [2 Marks]:\n- For Children with Intellectual Disability: Break tasks into small sequential steps (task analysis), emphasize daily life skills,\nsocial communication, and sheltered vocational training with immediate positive reinforcement.\n- For Gifted Children: Implement enrichment programs, flexible pacing, accelerated promotion, and independent research\nprojects to prevent boredom and nurture potential.",
        "explanation": ""
