        "id": 48,
        "type": "LA",
        "tag": "CBSE 2019 - 4/6 Marks",
        "question": "Describe the psychometric theories of intelligence proposed by Charles Spearman, Louis Thurstone, and Arthur Jensen.\nHighlight how each contributed to understanding intellectual structure. [6 Marks]",
        "answer": "Comprehensive review of psychometric models: (1) Charles Spearman's Two-Factor Theory (1927: General 'g'\nfactor as common mental energy + Specific 's' factors); (2) Louis Thurstone's Theory of Primary Mental Abilities (7\nindependent PMAs: V, N, S, P, W, M, R); (3) Arthur Jensen's Hierarchical Model (Level I associative learning vs\nLevel II cognitive competence); Structural synthesis.\nStep-by-Step Marking Scheme (2 Marks Spearman's Two-Factor Theory + 2 Marks Thurstone's Primary Mental Abilities + 2\nMarks Jensen's Hierarchical Model):\n• 1. Charles Spearman's Two-Factor Theory (1927) [2 Marks]:\n- Used factor analysis to propose that all intellectual performance involves two factors:\n- General Factor ('g' factor): A shared mental energy underlying all cognitive activities.\n- Specific Factors ('s' factors): Specialized abilities unique to specific tasks (e.g. musical, mechanical, or linguistic skills).\n• 2. Louis Thurstone's Theory of Primary Mental Abilities [2 Marks]:\n- Challenged Spearman's single 'g' factor, arguing intelligence consists of 7 relatively independent Primary Mental Abilities\n(PMAs):\n- Verbal Comprehension (V), Numerical Ability (N), Spatial Relations (S), Perceptual Speed (P), Word Fluency (W),\n\nAssociative Memory (M), and Inductive Reasoning (R).\n• 3. Arthur Jensen's Hierarchical Model [2 Marks]:\n- Organized mental abilities into two levels:\n- Level I (Associative Learning): Rote memory and direct recall where output closely matches input.\n- Level II (Cognitive Competence): Complex higher-order manipulation, abstract reasoning, and conceptual\ntransformation of information.",
