        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Examine the classification of 'Intelligence Tests' on the basis of: (a) Administration (Individual vs Group tests), (b) Nature of\nitems (Verbal, Non-Verbal, Performance tests), and (c) Cultural bias (Culture-fair vs Culture-biased tests). [6 Marks]",
        "answer": "Comprehensive taxonomy: (1) Administration: Individual tests (one-on-one, rapport, e.g. Stanford-Binet) vs\nGroup tests (mass administration, objective, e.g. Army Alpha); (2) Nature of items: Verbal (language-dependent)\nvs Non-verbal (geometric matrices, RPM) vs Performance (manipulation of objects, Bhatia/Kohs); (3) Cultural\nfairness: Culture-biased (reflects Western urban norms) vs Culture-fair (language-free, RPM, Cattell Culture Fair).",
        "explanation": "Step-by-Step Marking Scheme (2 Marks Administration + 2 Marks Nature of items + 2 Marks Cultural bias):\n• 1. Classification by Administration [2 Marks]:\n- Individual Tests: Administered to one individual at a time by a trained examiner; allows qualitative observation and\nrapport-building (e.g. Stanford-Binet, WAIS).\n- Group Tests: Administered simultaneously to large groups with standardized instructions; cost- and time-effective, but\nlimits individual observation (e.g. Army Alpha, Raven's Group Test).\n• 2. Classification by Nature of Items [2 Marks]:\n- Verbal Tests: Require reading, writing, or spoken language comprehension (cannot assess illiterate or language-impaired\nindividuals).\n- Non-Verbal Tests: Use pictures, symbols, or geometric patterns to assess reasoning without language dependencies.\n- Performance Tests: Require test-takers to manually arrange or construct physical materials under timed conditions (e.g.\nKohs' Block Design, Bhatia's Battery).\n• 3. Classification by Cultural Context [2 Marks]:\n- Culture-Biased Tests: Feature items, vocabulary, or cultural references familiar primarily to specific socioeconomic or\nWestern urban populations.\n- Culture-Fair Tests: Designed to minimize language and cultural dependencies by using abstract visual designs (e.g.\nRaven's Progressive Matrices)."
