        "answer": "Comprehensive examination: Levels of consciousness (Conscious, Preconscious, Unconscious; Iceberg model);\nTripartite structure: Id (Pleasure principle, instinctual, unconscious), Ego (Reality principle, executive branch),\nSuperego (Moral principle, conscience & ego-ideal); Four defense mechanisms: Repression, Projection, Reaction\nFormation, Sublimation.\nStep-by-Step Marking Scheme (1.5 Marks levels of consciousness + 2 Marks Id, Ego, Superego + 2.5 Marks four defense\nmechanisms with examples):\n• 1. Levels of Consciousness [1.5 Marks]:\n- Conscious: Thoughts, feelings, and perceptions of which a person is currently aware.\n- Preconscious: Information not in immediate awareness but easily accessible through recall.\n- Unconscious: The largest reservoir containing repressed desires, instinctual impulses, traumatic memories, and\nsexual/aggressive energy (the submerged bulk of the iceberg).\n• 2. Tripartite Structure of Personality [2 Marks]:\n- Id: Inborn, instinctual core operating on the 'pleasure principle'; demands immediate tension reduction through primary\nprocess thinking.\n- Ego: The executive operating on the 'reality principle'; balances the instinctual urges of the Id with the moral demands\nof the Superego using secondary process thinking.\n- Superego: The internal moral conscience internalized from parental and cultural standards; rewards virtuous behavior\nwith pride and punishes transgressions with guilt.\n• 3. Four Ego Defense Mechanisms [2.5 Marks]:\n- Repression: Unconsciously blocking traumatic memories or unacceptable impulses from conscious awareness (e.g.\nforgetting abuse).\n- Projection: Attributing one's own unacceptable impulses to others (e.g. an aggressive person accusing others of\nhostility).\n- Reaction Formation: Adopting attitudes and behaviors opposite to true unacceptable impulses (e.g. smothering an\nunliked sibling with excessive affection).\n- Sublimation: Redirecting unacceptable aggressive or sexual drives into constructive, creative activities (e.g. channeling\naggression into competitive sports).",
