        "id": 49,
        "type": "LA",
        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Examine the 'Type Approaches' to personality developed across history: (a) Hippocrates' humours, (b) Ayurvedic Tridoshas and\nTrigunas, (c) Carl Jung's Introversion-Extraversion, and (d) Friedman and Rosenman's Type-A and Type-B patterns. [6 Marks]",
        "answer": "Comprehensive review of typologies: (1) Hippocrates (4 humours: Sanguine, Phlegmatic, Choleric, Melancholic);\n(2) Ayurveda (Tridoshas: Vata, Pitta, Kapha; Trigunas: Sattva, Rajas, Tamas); (3) Carl Jung (Introverts vs\nExtraverts); (4) Friedman & Rosenman (Type-A vs Type-B, coronary heart disease link); Critique of typology (over-\nsimplification).\nStep-by-Step Marking Scheme (1.5 Marks Hippocrates + 1.5 Marks Ayurveda + 1.5 Marks Carl Jung + 1.5 Marks Friedman &\nRosenman):\n• 1. Hippocrates' Four Humours [1.5 Marks]:\n- Classified personality by bodily fluids: Sanguine (blood: cheerful, active), Phlegmatic (phlegm: calm, sluggish), Choleric\n(yellow bile: irritable, hot-tempered), and Melancholic (black bile: sad, depressed).\n• 2. Ayurvedic Tridoshas & Trigunas [1.5 Marks]:\n- Tridoshas: Vata, Pitta, and Kapha characterize biological constitutions.\n- Trigunas: Sattva (cleanliness, truth, wisdom), Rajas (passion, desire, action), and Tamas (lethargy, darkness, ignorance).\n• 3. Carl Jung's Typology [1.5 Marks]:\n- Introverts: Energy directed inward; contemplative, reserved, and reflective in solitary pursuits.\n- Extraverts: Energy directed outward; outgoing, sociable, adaptable, and action-oriented in social settings.\n• 4. Friedman and Rosenman: Type-A and Type-B [1.5 Marks]:\n- Type-A: Competitive, impatient, time-pressured, and hostile, with higher risks for coronary heart disease.\n- Type-B: Relaxed, unhurried, patient, and capable of working without intense time stress.",
        "explanation": ""
