        "question": "Examine the physiological, emotional, cognitive, and behavioural effects of stress on human functioning. Provide clear\nempirical manifestations of each. [6 Marks]",
        "answer": "Comprehensive examination: Four functional domains; (1) Physiological effects (Adrenaline/cortisol release,\nhypertension, heart disease, suppressed immunity); (2) Emotional effects (Mood swings, irritability, anxiety,\ndepression); (3) Cognitive effects (Reduced memory recall, poor concentration, catastrophic thinking); (4)\nBehavioural effects (Disrupted sleep/diet, substance use, absenteeism).",
        "explanation": "Step-by-Step Marking Scheme (1.5 Marks each for Physiological, Emotional, Cognitive, and Behavioural effects):\n• 1. Physiological Effects [1.5 Marks]:\n- Activation of the sympathetic nervous system and the adrenal glands, leading to elevated heart rate, high blood\npressure, and shallow breathing.\n- Chronic stress elevates cortisol levels, suppressing immune functioning and contributing to psychosomatic conditions\n(e.g. ulcers, tension headaches).\n• 2. Emotional Effects [1.5 Marks]:\n- Manifests as persistent irritability, mood swings, feelings of anxiety, emotional exhaustion, and feelings of helplessness.\n• 3. Cognitive Effects [1.5 Marks]:\n- Impairs attention and working memory, leading to indecisiveness, poor problem-solving, and cognitive errors.\n- Fosters negative thought loops and catastrophic cognitive appraisals.\n• 4. Behavioural Effects [1.5 Marks]:\n- Disrupted eating patterns (overeating or loss of appetite) and sleep disturbances (insomnia).\n- Increased reliance on maladaptive behaviors like smoking or alcohol use, alongside workplace absenteeism."
