        "answer": "Detailed examination: Four stress management techniques; (1) Relaxation techniques (Deep breathing, PMR,\ncalming autonomic arousal); (2) Biofeedback (Electronic monitoring, voluntary control over physiological\nparameters); (3) Creative visualization (Guided imagery, peaceful scenes, mental rehearsal); (4) Cognitive\nrestructuring (Challenging irrational thoughts, cognitive reframing).\nStep-by-Step Marking Scheme (1.5 Marks each for Relaxation, Biofeedback, Creative Visualization, and Cognitive\nRestructuring):\n• 1. Relaxation Techniques [1.5 Marks]:\n- Progressive Muscle Relaxation (PMR) and deep rhythmic diaphragmatic breathing reduce sympathetic nervous system\narousal, lowering heart rate and muscle tension.\n• 2. Biofeedback Training [1.5 Marks]:\n- Electronic instruments monitor physiological signals (e.g. brain waves, skin conductance) and provide real-time\nfeedback, helping individuals learn conscious control over autonomic responses.\n• 3. Creative Visualization [1.5 Marks]:\n- Individuals visualize peaceful sensory scenes or mentally rehearse successfully navigating stressful situations, which\nhelps lower anxiety.\n• 4. Cognitive Restructuring [1.5 Marks]:\n- Identifies cognitive distortions, irrational assumptions, and catastrophic self-talk, replacing them with balanced,\nevidence-based coping thoughts.",
