        "answer": "Comprehensive review: Life skills (WHO definition: abilities for adaptive and positive behavior); (1) Assertiveness\n(Expressing feelings and rights confidently without aggression); (2) Time management (Prioritization, setting\nboundaries, avoiding procrastination); (3) Rational thinking (Correcting cognitive errors); Positive health\noutcomes.\nStep-by-Step Marking Scheme (1 Mark definition + 1.5 Marks Assertiveness + 1.5 Marks Time management + 1.5 Marks\nRational thinking + 0.5 Mark positive health outcomes):\n• 1. Concept of Life Skills [1 Mark]:\n- Life skills are adaptive competencies that enable individuals to handle the demands and challenges of everyday life\nconstructively.\n• 2. Assertiveness [1.5 Marks]:\n- Communicating needs, boundaries, and opinions clearly and respectfully, allowing individuals to decline unreasonable\nrequests without guilt or anger.\n• 3. Time Management [1.5 Marks]:\n- Organizing daily tasks by priority, setting realistic deadlines, delegating responsibilities, and avoiding procrastination to\nreduce time-pressure stress.\n• 4. Rational Thinking [1.5 Marks]:\n- Identifying distorted beliefs and reframing problems realistically rather than interpreting setbacks catastrophically.\n• 5. Positive Health Outcomes [0.5 Mark]:\n- These skills foster psychological hardiness, reduce vulnerability to burnout, and support emotional balance.",
