        "id": 41,
        "type": "LA",
        "tag": "CBSE 2024 - 4/6 Marks",
        "question": "Examine 'Schizophrenia Spectrum Disorders'. Detail the clinical manifestations across: (a) Positive Symptoms (Delusions,\nHallucinations, Disorganized speech), (b) Negative Symptoms (Avolition, Alogia, Anhedonia, Flat affect), and (c) Psychomotor\nSymptoms (Catatonia). [6 Marks]",
        "answer": "Comprehensive examination: Severe psychotic disorder; Positive symptoms (Delusions of persecution, reference,\ngrandeur, control; Hallucinations: Auditory, visual, olfactory; Formal thought disorder: loose associations,\nneologisms); Negative symptoms (Avolition, Alogia, Anhedonia, Flat affect, Asociality); Psychomotor symptoms\n\n(Catatonic stupor, rigidity, posturing, waxy flexibility).\nStep-by-Step Marking Scheme (2.5 Marks Positive Symptoms + 2 Marks Negative Symptoms + 1.5 Marks Psychomotor\nSymptoms):\n• 1. Positive Symptoms (Excesses of Function) [2.5 Marks]:\n- Delusions: Fixed false beliefs resistant to contradictory evidence, including delusions of persecution (being plotted\nagainst), reference (messages meant for them), grandeur (believing one has divine powers), and control (being operated\nby outside forces).\n- Hallucinations: False sensory perceptions without external stimuli; auditory hallucinations (hearing voices) are most\ncommon, though visual, olfactory, tactile, and gustatory forms occur.\n- Disorganized Thinking & Speech: Derailment (loose associations), neologisms (inventing nonsensical words), and\nperseveration (repeating words continuously).\n• 2. Negative Symptoms (Deficits of Function) [2 Marks]:\n- Avolition: Inability to initiate or persist in goal-directed activities.\n- Alogia: Poverty of speech in fluency and content.\n- Anhedonia: Inability to experience pleasure from previously enjoyed activities.\n- Flat Affect: Lack of visible emotional reactivity and expression.\n• 3. Psychomotor Symptoms [1.5 Marks]:\n- Catatonic Stupor: Complete motor immobility and mutism.\n- Catatonic Rigidity: Resisting efforts to be moved.\n- Waxy Flexibility: Allowing limbs to be molded into postures that are then held rigidly.",
