        "question": "Examine 'Anxiety Disorders'. Discuss the symptoms, psychological mechanisms, and clinical characteristics of: (a) Generalized\nAnxiety Disorder (GAD), (b) Panic Disorder, (c) Phobias, and (d) Separation Anxiety Disorder. [6 Marks]",
        "answer": "Comprehensive review of anxiety disorders: Autonomic hyperactivity and dread; (1) Generalized Anxiety Disorder\n(Chronic unfocused worry, motor tension, hypervigilance for 6+ months); (2) Panic Disorder (Recurrent\nunexpected panic attacks, fear of dying/madness); (3) Phobias (Specific phobia, social anxiety, agoraphobia); (4)\nSeparation Anxiety Disorder (Distress regarding separation from attachment figures).",
        "explanation": "Step-by-Step Marking Scheme (1.5 Marks each for GAD, Panic Disorder, Phobias, and Separation Anxiety Disorder):\n• 1. Generalized Anxiety Disorder (GAD) [1.5 Marks]:\n- Persistent, excessive, and uncontrollable worry about multiple everyday life events lasting at least 6 months.\n- Accompanied by physical symptoms: motor tension, restlessness, fatigue, muscle aches, and sleep disturbance.\n• 2. Panic Disorder [1.5 Marks]:\n- Characterized by recurrent, unexpected panic attacks that surge within minutes.\n- Symptoms include palpitations, trembling, sweating, dyspnea, and an intense fear of dying or losing control.\n• 3. Phobias [1.5 Marks]:\n- Intense, irrational fears of specific objects or situations that lead to avoidance behaviors.\n- Includes Specific Phobias (animals, heights), Social Anxiety Disorder (fear of negative evaluation in social situations), and\nAgoraphobia (fear of inescapable public spaces).\n• 4. Separation Anxiety Disorder [1.5 Marks]:\n- Developmentally inappropriate and excessive fear or anxiety concerning separation from major attachment figures,\noften manifesting as school refusal or reluctance to sleep alone."
