        "tag": "CBSE 2023 - 4/6 Marks",
        "question": "Discuss 'Somatic Symptom and Related Disorders'. Compare and contrast: (a) Somatic Symptom Disorder, (b) Illness Anxiety\nDisorder, and (c) Conversion Disorder. Highlight the psychological factors underlying these conditions. [6 Marks]",
        "answer": "Detailed comparative analysis: Physical symptoms without medical etiology; (1) Somatic Symptom Disorder\n\n(Distressing bodily symptoms, disproportionate anxiety); (2) Illness Anxiety Disorder (Hypochondriasis,\npreoccupation with illness, minimal somatic symptoms); (3) Conversion Disorder (Voluntary motor/sensory\ndeficits, la belle indifférence); Psychological etiology (Secondary gain, trauma conversion).\nStep-by-Step Marking Scheme (2 Marks Somatic Symptom Disorder + 2 Marks Illness Anxiety Disorder + 2 Marks\nConversion Disorder & psychological mechanisms):\n• 1. Somatic Symptom Disorder [2 Marks]:\n- Involves one or more distressing physical symptoms (e.g. chronic pain, gastrointestinal distress) that disrupt daily life.\n- Accompanied by excessive thoughts, anxiety, and time devoted to these health concerns, despite negative medical\nevaluations.\n• 2. Illness Anxiety Disorder (Hypochondriasis) [2 Marks]:\n- Marked by preoccupation with having or developing a serious undiagnosed medical illness, with minimal or mild\nphysical complaints.\n- Individuals engage in repetitive health-related checks or show excessive avoidance of medical settings.\n• 3. Conversion Disorder & Psychological Mechanisms [2 Marks]:\n- Involves unexplained alterations or losses in voluntary motor or sensory functions (e.g. paralysis, blindness, aphonia).\n- The physical deficit serves an unconscious psychological function (converting emotional distress into physical\nsymptoms), often displaying *la belle indifférence*.",
