        "answer": "Comprehensive examination: Disruption of identity, memory, and consciousness; (1) Dissociative Amnesia\n(Sudden memory loss for trauma); (2) Dissociative Fugue (Unexpected flight, identity assumption); (3)\nDepersonalization/Derealization (Out-of-body detachment, dreamlike world); (4) Dissociative Identity Disorder\n(Multiple personality alters, trauma defense).\nStep-by-Step Marking Scheme (1.5 Marks each for Dissociative Amnesia, Fugue, Depersonalization, and Dissociative\nIdentity Disorder):\n• 1. Dissociative Amnesia [1.5 Marks]:\n- An inability to recall important personal autobiographical memories, usually of a stressful or traumatic nature, that\ncannot be explained by ordinary forgetfulness.\n• 2. Dissociative Fugue [1.5 Marks]:\n- Characterized by unexpected travel away from home or workplace, accompanied by amnesia for past identity and\nsometimes the adoption of a new persona.\n• 3. Depersonalization / Derealization Disorder [1.5 Marks]:\n- Depersonalization: Feeling detached from one's own mental processes or physical body (as if observing oneself from the\noutside).\n- Derealization: Experiencing the external world as dreamlike, artificial, or distorted.\n• 4. Dissociative Identity Disorder (DID) [1.5 Marks]:\n- The presence of two or more distinct personality states (alters) that recurrently take control of behavior, often linked to\nsevere, prolonged childhood trauma.",
