        "type": "LA",
        "tag": "CBSE 2022 - 4/6 Marks",
        "question": "Discuss 'Mood Disorders'. Differentiate between 'Major Depressive Disorder' and 'Bipolar Disorder'. Explain the cognitive\nmodel of depression proposed by Aaron Beck and the learned helplessness model by Martin Seligman. [6 Marks]",
        "answer": "Detailed examination: Disturbances in affect; Major Depressive Disorder (Unipolar, sad mood, anhedonia,\nvegetative signs) vs Bipolar Disorder (Bipolar I/II, alternating mania and depression); Aaron Beck's Cognitive Triad\n(Negative view of self, world, and future; cognitive distortions); Martin Seligman's Learned Helplessness\n\n(Uncontrollable aversive events, internal-stable-global attributions).\nStep-by-Step Marking Scheme (2 Marks MDD vs Bipolar + 2 Marks Beck's Cognitive Model + 2 Marks Seligman's Learned\nHelplessness):\n• 1. Major Depressive Disorder versus Bipolar Disorder [2 Marks]:\n- MDD (Unipolar): Involves persistent low mood, loss of interest/pleasure, fatigue, and feelings of worthlessness, without\nmanic episodes.\n- Bipolar Disorder: Characterized by alternating periods of major depression and mania (euphoria, grandiosity, reduced\nneed for sleep, impulsivity).\n• 2. Aaron Beck's Cognitive Theory of Depression [2 Marks]:\n- Proposes that depression is maintained by negative automatic schemas and the 'Cognitive Triad': negative views of\noneself ('I am defective'), the world ('The world is hostile'), and the future ('Things will never improve').\n- Maintained by cognitive distortions such as overgeneralization, catastrophizing, and all-or-nothing thinking.\n• 3. Martin Seligman's Learned Helplessness Model [2 Marks]:\n- Suggests that individuals develop depression when they experience uncontrollable negative life events and conclude\nthat their actions cannot change outcomes.\n- Compounded by a pessimistic attributional style: attributing negative events to internal ('It's my fault'), stable ('It will\nnever change'), and global ('It ruins everything') causes.",
        "explanation": ""
