        "answer": "Detailed examination: Early developmental conditions; (1) ADHD: Diagnostic criteria (Inattention, hyperactivity,\nimpulsivity across settings; classroom disruptions; behavioral interventions: token economy, parent training,\nstimulants); (2) Autism Spectrum Disorder: Diagnostic criteria (Deficits in social-emotional reciprocity, non-verbal\ncommunication, repetitive behaviors, sameness, sensory sensitivity; interventions: Applied Behavior Analysis,\nspeech therapy).\nStep-by-Step Marking Scheme (3 Marks ADHD profile & interventions + 3 Marks Autism Spectrum Disorder profile &\ninterventions):\n• 1. Attention-Deficit/Hyperactivity Disorder (ADHD) [3 Marks]:\n- Diagnostic Criteria & Symptoms: Inattention (careless mistakes, distractibility, failure to follow instructions),\nHyperactivity (fidgeting, restlessness), and Impulsivity (blurting answers, inability to wait turn).\n- Interventions: Behavioral therapy using structured routines, token reinforcement, parent management training, and\npharmacological support when indicated.\n• 2. Autism Spectrum Disorder (ASD) [3 Marks]:\n- Diagnostic Criteria & Symptoms: Persistent deficits in social communication (lack of joint attention, poor eye contact,\nflat reciprocity) and restricted, repetitive patterns of behavior, insistence on sameness, and atypical sensory reactions.\n- Interventions: Early intensive behavioral intervention (Applied Behavior Analysis), structured communication training,\nand social skills coaching.",
