        "question": "Discuss 'Substance-Related and Addictive Disorders'. Explain: (a) Dependence versus Abuse, (b) Tolerance and Withdrawal, and\n(c) The physiological and psychological effects of Alcohol abuse. [6 Marks]",
        "answer": "Comprehensive examination: Substance disorders; (1) Abuse vs Dependence; (2) Tolerance (progressively higher\ndoses required) and Withdrawal (autonomic/psychological distress upon cessation, e.g. delirium tremens); (3)\nAlcohol: Depressant action on GABA, impaired motor control, cognitive blunting, cirrhosis of liver, Wernicke-\nKorsakoff syndrome, family devastation.\nStep-by-Step Marking Scheme (2 Marks Abuse vs Dependence + 2 Marks Tolerance and Withdrawal + 2 Marks Alcohol\n\neffects):\n• 1. Substance Abuse versus Substance Dependence [2 Marks]:\n- Substance Abuse: Recurrent substance use resulting in failure to fulfill role obligations, hazardous use, and interpersonal\nproblems without physical addiction.\n- Substance Dependence: Severe physiological addiction marked by uncontrollable craving, loss of control over\nconsumption, tolerance, and withdrawal.\n• 2. Tolerance and Withdrawal [2 Marks]:\n- Tolerance: The physiological adaptation requiring larger doses to produce the effect previously achieved with smaller\namounts.\n- Withdrawal: A cluster of distressing, potentially dangerous physical and cognitive symptoms (tremors, seizures, anxiety)\noccurring when substance use is stopped.\n• 3. Effects of Alcohol Abuse [2 Marks]:\n- Physiological: Acts as a central nervous system depressant (stimulating GABA), damaging the liver (cirrhosis),\ncardiovascular system, and causing nutritional brain damage.\n- Psychological: Impairs judgment, slurs speech, produces emotional volatility, and often strains family and professional\nrelationships.",
        "explanation": ""
