        "answer": "Detailed comparative examination: (1) Anorexia Nervosa (Self-starvation, distorted body image, <85% expected\nweight, amenorrhea, cardiac arrhythmias, high mortality); (2) Bulimia Nervosa (Binge eating, purging:\nvomiting/laxatives, normal weight, tooth enamel erosion, electrolyte imbalance); Socio-cultural pressures (Media\nthin-ideal, fashion standards, peer teasing).",
        "explanation": "Step-by-Step Marking Scheme (2.5 Marks Anorexia Nervosa + 2.5 Marks Bulimia Nervosa + 1 Mark socio-cultural etiology):\n• 1. Anorexia Nervosa [2.5 Marks]:\n- Clinical Features: Relentless pursuit of thinness through food restriction, distorted body perception, and intense fear of\ngaining weight.\n- Medical Hazards: Severe emaciation, electrolyte imbalances, cardiac arrhythmias, hypothermia, bone loss, and potential\nmortality.\n• 2. Bulimia Nervosa [2.5 Marks]:\n- Clinical Features: Recurrent, secretive binge eating followed by compensatory purging (vomiting, laxative abuse,\nexcessive exercise); individuals typically maintain near-normal weight.\n- Medical Hazards: Gastric tears, erosion of dental enamel from stomach acid, potassium depletion, and cardiac\ncomplications.\n• 3. Socio-Cultural Pressures [1 Mark]:\n- Mass media and social networks reinforce idealized thin standards, equating slimness with success and driving body\ndissatisfaction."
