        "tag": "CBSE 2018 - 4/6 Marks",
        "question": "Analyze the 'Diathesis-Stress Model' of abnormal behaviour. How does this integrative framework reconcile biological\npredispositions, cognitive vulnerabilities, and environmental life stressors in explaining psychiatric conditions? [6 Marks]",
        "answer": "Analytical exposition: Integrative biopsychosocial framework; Diathesis (Inherent biological predisposition: genes,\nneurochemistry, temperament, or psychological cognitive vulnerability); Stressor (Environmental precipitating\nevents: trauma, poverty, relationship loss); Additive interaction (High diathesis needs low stress, low diathesis\nneeds high stress); Applications to Schizophrenia and Depression.\nStep-by-Step Marking Scheme (2 Marks Diathesis definition + 2 Marks Stressor definition + 2 Marks interactive dynamics &\n\nclinical examples):\n• 1. Concept of Diathesis [2 Marks]:\n- Diathesis refers to a preexisting biological, genetic, or psychological vulnerability to developing a disorder (e.g. genetic\nrisk for schizophrenia, low serotonin, or cognitive vulnerability).\n• 2. Role of Environmental Stressors [2 Marks]:\n- Stressors represent environmental triggers (e.g. severe childhood trauma, economic distress, marital conflict, or\nbereavement) that place demands on personal coping resources.\n• 3. Interactive Dynamics & Clinical Applications [2 Marks]:\n- A psychological disorder emerges from the interaction between diathesis and stress; having a genetic predisposition\ndoes not guarantee illness unless triggered by environmental stressors.\n- In Major Depression, for instance, an individual with a genetic vulnerability or pessimistic cognitive style may function\nwell until an acute life crisis triggers a depressive episode.",
        "explanation": ""
