        "tag": "CBSE 2017 - 4/6 Marks",
        "question": "Evaluate the role of 'Alternative Therapies' in contemporary mental health care. Discuss how practices like Yoga, Pranayama,\nMeditation (such as Sudarshan Kriya Yoga and Vipassana), and Mindfulness complement conventional psychotherapy. [6\nMarks]",
        "answer": "Evaluative synthesis: Integration of Eastern mind-body practices with Western psychotherapy; Physiological\nmechanisms (Vagal stimulation, down-regulation of HPA axis, neuroplasticity); Clinical applications: Sudarshan\nKriya Yoga (SKY) for depression/PTSD, Vipassana for emotional self-regulation, Mindfulness-Based Cognitive\nTherapy (MBCT) for preventing depressive relapse; Integrative paradigm.\nStep-by-Step Marking Scheme (1.5 Marks integrative mind-body paradigm + 2 Marks physiological mechanisms + 2.5\nMarks specific practices and clinical benefits):\n• 1. Integrative Mind-Body Paradigm [1.5 Marks]:\n- Alternative and complementary therapies integrate traditional mind-body practices with clinical psychology, treating\nmental health holistically.\n• 2. Physiological & Neurological Mechanisms [2 Marks]:\n- Rhythmic breathing and mindfulness stimulate the vagus nerve, increase parasympathetic activity, lower resting heart\nrate, and down-regulate cortisol levels.\n- Regular meditation supports neuroplasticity, strengthening connections in brain regions responsible for executive\nattention and emotion regulation.\n• 3. Specific Practices & Clinical Benefits [2.5 Marks]:\n- Sudarshan Kriya Yoga (SKY): Clinical studies demonstrate that its structured rhythmic breathing cycles help alleviate\nsymptoms of depression and post-traumatic stress.\n- Vipassana & Mindfulness: Non-judgmental awareness of present thoughts and sensations reduces rumination, forming\nthe basis of evidence-based interventions like Mindfulness-Based Cognitive Therapy (MBCT) for preventing depression\nrelapse.",
        "explanation": ""
