        "question": "Examine Solomon Asch's classic experiment on 'Conformity' (1951). Describe the experimental design, findings, the role of\nunanimous majorities, and explain why individuals conform under peer pressure. [6 Marks]",
        "answer": "Comprehensive examination: Asch's line judgment experiment; Experimental setup (Standard line vs three\ncomparison lines; 7-9 individuals, only 1 true subject, rest confederates); Findings (75% conformed at least once,\noverall 37% conformity on critical trials); Factors influencing conformity: Group size (peaks at 3-4), Unanimity\n(dissenter drops conformity to 5%); Informational vs Normative influence.\nStep-by-Step Marking Scheme (2 Marks experimental methodology & findings + 2 Marks determinants of conformity + 2\nMarks informational vs normative explanations):\n• 1. Experimental Methodology & Findings [2 Marks]:\n- Design: Naive participants were placed in a room with 6–8 confederates to judge which of three comparison lines\nmatched a standard line.\n- Findings: Confederates gave unanimously incorrect answers on 12 critical trials; 75% of participants conformed on at\nleast one trial, with an overall conformity rate of ~37%.\n• 2. Determinants of Conformity [2 Marks]:\n- Group Size: Conformity increased as group size grew to 3–4 unanimous confederates, leveling off beyond that.\n- Unanimity: When a single confederate broke consensus by giving the correct answer, conformity plummeted from 37%\nto under 5%.\n• 3. Why Individuals Conform [2 Marks]:\n- Normative Social Influence: Conforming to gain approval, avoid embarrassment, and escape group ostracism.\n- Informational Social Influence: Conforming because the individual questions their own perception and looks to the\nmajority for accurate information.",
        "explanation": ""
