        "question": "Examine Stanley Milgram's classic study on 'Obedience to Authority' (1963). Describe the experimental setup, findings,\nsituational determinants of obedience, and discuss the ethical controversies surrounding the study. [6 Marks]",
        "answer": "Comprehensive review: Yale laboratory study; Experimental setup ('Teacher' administering shock to 'Learner'\nconfederate in 15V increments up to 450V under experimenter's prods); Findings (65% fully obeyed to 450V,\ndespite extreme learner distress); Situational factors: Legitimacy of authority, Proximity to victim, Proximity of\nauthority, Gradual escalation; Ethical critique (Psychological distress, deception).\nStep-by-Step Marking Scheme (2 Marks setup & findings + 2.5 Marks situational determinants + 1.5 Marks ethical\ncontroversies):\n• 1. Experimental Setup & Findings [2 Marks]:\n- Setup: Participants ('teachers') were instructed by a lab-coated researcher to administer increasingly severe electric\nshocks (15V to 450V) to a confederate ('learner') for memory errors.\n- Findings: Despite the learner's pre-recorded screams and eventual silence, 65% of participants obeyed orders to deliver\nthe maximum 450-volt shock.\n• 2. Situational Determinants of Obedience [2.5 Marks]:\n- Perceived Legitimacy: The prestigious university setting and scientific authority lent credibility to the commands.\n- Proximity to Authority: Physical presence of the experimenter in the room sustained obedience; orders over the phone\ndropped obedience to 20%.\n- Proximity to Victim: Placing the learner in the same room lowered obedience to 40%.\n- Gradual Escalation: Shocks increased in small 15V increments, drawing participants deeper into compliance.\n• 3. Ethical Controversies [1.5 Marks]:\n- Criticized for causing severe psychological stress (trembling, sweating, stuttering), using extensive deception, and raising\nquestions about informed consent.",
        "explanation": ""
