        "question": "Discuss 'Social Loafing' in collective tasks. Detail the psychological causes underlying social loafing, and outline six concrete\nmanagerial and pedagogical strategies to eliminate it in workplaces and school projects. [6 Marks]",
        "answer": "Comprehensive examination: The Ringelmann effect; Psychological causes: Diffusion of responsibility, Low\nindividual accountability, Low perceived value of task, Free-rider effect; Strategies: (1) Make individual efforts\nidentifiable; (2) Assign distinct responsibilities; (3) Keep groups small; (4) Provide individual performance\nfeedback; (5) Emphasize task importance; (6) Build group cohesiveness.",
        "explanation": "Step-by-Step Marking Scheme (2.5 Marks psychological causes + 3.5 Marks practical elimination strategies):\n• 1. Psychological Causes of Social Loafing [2.5 Marks]:\n- Diffusion of Responsibility: When individual contributions are pooled into a group total, individuals feel less personal\naccountability.\n- Decreased Evaluation Apprehension: Members believe their effort cannot be isolated or judged, reducing motivation to\nperform.\n- Perceived Redundancy: Members believe the group will succeed without their contribution (the 'free-rider' effect).\n• 2. Strategies to Eliminate Social Loafing [3.5 Marks - roughly 0.6 Mark each]:\n- Individual Identifiability: Assign separate, measurable sub-tasks to each member to track individual effort.\n- Maintain Smaller Teams: Keep group sizes small to make withdrawal of effort immediately apparent.\n- Task Meaningfulness: Communicate the importance and real-world relevance of the collective assignment.\n- Performance Feedback: Provide individual performance appraisals alongside group evaluations.\n- Build Cohesiveness: Foster mutual commitment so members value the success of their peers.\n- Peer Evaluations: Use confidential peer reviews to ensure accountability among team members."
