        "type": "LA",
        "tag": "CBSE 2023 - 4/6 Marks",
        "question": "Analyze Irving Janis's concept of 'Groupthink'. Detail the historical context, preconditions, eight primary symptoms, and outline\nfour institutional safeguards to prevent groupthink in leadership cabinets. [6 Marks]",
        "answer": "Comprehensive analysis: Flawed decision-making in cohesive groups; Preconditions (High cohesiveness, structural\ninsulation, directive leadership, crisis stress); Eight symptoms: Invulnerability, collective rationalization, inherent\nmorality, outgroup stereotyping, self-censorship, illusion of unanimity, direct pressure, mindguards; Historical\nexamples (Bay of Pigs, Challenger); Institutional safeguards (Devil's advocate, outside experts, second-chance\nmeetings).",
        "explanation": "Step-by-Step Marking Scheme (1.5 Marks preconditions + 2.5 Marks symptoms + 2 Marks preventative safeguards):\n• 1. Preconditions of Groupthink [1.5 Marks]:\n- High group cohesiveness, insulation from outside feedback, a directive leader who states preferences early, and high\nstress from acute threats.\n• 2. Primary Symptoms of Groupthink [2.5 Marks]:\n- Illusion of Invulnerability: Creating unwarranted optimism that leads to high-risk decisions.\n- Collective Rationalization: Discounting warnings that challenge group assumptions.\n- Belief in Inherent Morality: Overlooking ethical consequences of group actions.\n- Outgroup Stereotyping: Viewing opponents as too weak or evil to negotiate with.\n- Direct Pressure & Self-Censorship: Silencing internal misgivings and pressuring dissenters.\n- Mindguards: Members shielding the leader from contradictory information.\n• 3. Institutional Safeguards [2 Marks]:\n- Designate a rotating 'Devil's Advocate' to challenge group assumptions systematically.\n- Invite independent outside experts to review decision frameworks.\n- Break into independent sub-groups to develop separate recommendations before reconvening.\n- Hold 'second-chance' meetings to reconsider choices before finalizing decisions."
