        "answer": "Detailed examination: Interpersonal influence techniques; (1) Foot-in-the-Door (Small request agreed to ->\ncommitment -> larger target request); (2) Door-in-the-Face (Extreme request refused -> concession -> moderate\ntarget request); (3) Low-Ball (Favorable terms committed -> terms changed); (4) That's-Not-All (Sweetening deal\nwith bonus before decision); Psychological mechanisms (Commitment, Reciprocity, Consistency).",
        "explanation": "Step-by-Step Marking Scheme (1.5 Marks each for the four compliance techniques):\n• 1. Foot-in-the-Door Technique [1.5 Marks]:\n- Mechanism: Relies on the principle of self-consistency; agreeing to a minor initial request alters self-perception, making\nthe target more likely to agree to a larger subsequent request.\n- Application: A charity asking someone to sign a petition, followed by a request for a monetary donation.\n• 2. Door-in-the-Face Technique [1.5 Marks]:\n- Mechanism: Relies on reciprocal concessions; refusing an extreme request creates social discomfort, making the target\nview the smaller subsequent request as a reasonable compromise.\n- Application: Asking for a $1,000 donation, and when refused, asking for $25.\n• 3. Low-Ball Technique [1.5 Marks]:\n- Mechanism: Secures an initial commitment based on favorable terms; when terms are revised upward, internal\ncommitment keeps the target from backing out.\n- Application: Car sales where a low price is agreed upon, followed by added fees for essential accessories.\n• 4. That's-Not-All Technique [1.5 Marks]:\n- Mechanism: Sweetens an offer with bonuses or discounts before the customer decides, framing the addition as an\nimmediate personal concession.\n- Application: Informercials offering extra items 'at no extra cost' to prompt immediate purchases."
