        "answer": "Analytical exposition: Interdependent social dynamics; Prisoner's Dilemma (Cooperation vs Defection matrix,\nmutual benefit vs betrayal risk); Determinants of cooperation: (1) Reward structure (Cooperative\ninterdependence vs zero-sum competitive structure); (2) Interpersonal communication (Dialogue builds trust); (3)\nReciprocity (Tit-for-tat strategies); Real-world applications.\nStep-by-Step Marking Scheme (2 Marks Prisoner's Dilemma + 3 Marks determinants of cooperation + 1 Mark real-world\napplication):\n• 1. The Prisoner's Dilemma Paradigm [2 Marks]:\n- A game-theoretic matrix where two players must choose between cooperation (mutual silence) and defection\n(confession).\n- If both cooperate, both receive a light sentence; if both defect, both receive heavy sentences; if one defects while the\nother cooperates, the defector goes free while the cooperator receives the maximum penalty.\n• 2. Determinants of Cooperation [3 Marks - 1 Mark each]:\n- Reward Structure: Cooperative structures (where individual success depends on team success) foster teamwork;\ncompetitive zero-sum structures foster defection.\n- Interpersonal Communication: Open, direct dialogue allows parties to discuss intentions, establish trust, and coordinate\nstrategies.\n- Reciprocity Norm: Cooperative behavior typically elicits cooperative responses, while competitive defection prompts\nretaliation.\n• 3. Real-World Applications [1 Mark]:\n- Helps model international climate agreements, trade negotiations, and community shared-resource management.",
