        "answer": "Detailed examination: Structural framework of groups; (1) Roles (Socially defined behavioral expectations, role\nconflict); (2) Norms (Unwritten shared standards of conduct, enforcement via sanctions); (3) Status (Relative\nsocial prestige/power hierarchy); (4) Cohesiveness (Mutual attraction, we-feeling); Maintenance of order and\ncoordination.",
        "explanation": "Step-by-Step Marking Scheme (1.5 Marks each for Roles, Norms, Status, and Cohesiveness):\n• 1. Group Roles [1.5 Marks]:\n- Socially defined expectations for how a person in a specific position should behave; provides functional division of labor,\nthough conflicting expectations can produce role strain.\n• 2. Group Norms [1.5 Marks]:\n- Unwritten, shared standards of acceptable behavior that guide member actions; enforced through informal rewards\n(approval) and sanctions (disapproval).\n• 3. Status Hierarchy [1.5 Marks]:\n- The relative social standing, prestige, or authority held by individuals within the group; determines influence in decision-\nmaking and access to resources.\n• 4. Group Cohesiveness [1.5 Marks]:\n- The strength of interpersonal attraction and shared solidarity holding members together; high cohesiveness increases\nmember satisfaction and productivity on well-defined tasks."
