        "question": "Discuss Henri Tajfel's 'Social Identity Theory'. Explain the cognitive processes of Social Categorization, Social Identification, and\nSocial Comparison, and show how ingroup favouritism and outgroup derogation develop. [6 Marks]",
        "answer": "Comprehensive review of social identity; Henri Tajfel's minimal group paradigm; Three cognitive stages: (1) Social\nCategorization (Sorting self and others into groups); (2) Social Identification (Adopting group identity, self-esteem\nlink); (3) Social Comparison (Comparing ingroup with outgroups favorably); Ingroup favoritism and outgroup\nderogation.\nStep-by-Step Marking Scheme (1.5 Marks theoretical rationale + 3 Marks three cognitive stages + 1.5 Marks ingroup\nfavoritism & outgroup derogation):\n• 1. Theoretical Rationale [1.5 Marks]:\n- Henri Tajfel proposed that personal identity is partly derived from membership in social groups; individuals strive to\nachieve positive social identity to enhance self-esteem.\n• 2. Three Core Cognitive Stages [3 Marks - 1 Mark each]:\n- Social Categorization: Cognitive classification of people into social categories ('us' vs 'them') to simplify social\nperception.\n- Social Identification: Adopting the identity, values, and norms of one's group, making group success feel like personal\nsuccess.\n- Social Comparison: Comparing one's ingroup against relevant outgroups along evaluative dimensions.\n• 3. Ingroup Favoritism & Outgroup Derogation [1.5 Marks]:\n- To maintain positive distinctiveness, members favor their own group in resource allocation and view outgroups through\nnegative, homogenized stereotypes.",
