        "answer": "Analytical exposition: Loss of individual self-awareness; Situational triggers (Anonymity, diffuse responsibility,\nsensory overload, collective arousal); Psychological consequences (Reduced self-monitoring, weakened social\ninhibitions, susceptibility to mob contagion); Famous studies (Zimbardo's Stanford prison study); Crowd control\n\nstrategies.\nStep-by-Step Marking Scheme (2 Marks situational triggers + 2.5 Marks psychological mechanisms & consequences + 1.5\nMarks research evidence & mitigation):\n• 1. Situational Triggers [2 Marks]:\n- Physical Anonymity: Being submerged in large crowds or wearing uniforms/masks reduces feelings of being identifiable.\n- Diffused Responsibility: Collective group action dilutes individual felt responsibility.\n- Heightened Physiological Arousal: Noise, movement, and emotional chanting intensify sensory stimulation.\n• 2. Psychological Mechanisms & Consequences [2.5 Marks]:\n- Reduced Self-Awareness: Shift from internal moral standards to external situational cues.\n- Loss of Restraint: Lowered self-control can lead to impulsive, anti-social, or aggressive collective actions (e.g. mob\nviolence or looting).\n• 3. Research Evidence & Mitigation [1.5 Marks]:\n- Demonstrated in Philip Zimbardo's experiments, where anonymity increased aggressive behavior.\n- Mitigation: Increasing individual visibility, using mirrors, and directly addressing individuals by name helps restore\npersonal self-awareness.",
