        "question": "\"Human beings are fundamentally social organisms whose choices, morals, and identities are continuously mediated by\ngroups.\" Critically evaluate this statement using evidence from conformity, obedience, and social identity research. [6 Marks]",
        "answer": "Critical evaluation: The power of the social situation; (1) Conformity evidence (Asch: peer consensus overrides\nsensory evidence); (2) Obedience evidence (Milgram: authority commands override personal conscience); (3)\nSocial identity evidence (Tajfel: group labels generate ingroup bias); Human autonomy vs social influence\nsynthesis.\nStep-by-Step Marking Scheme (1.5 Marks conformity evidence + 1.5 Marks obedience evidence + 1.5 Marks social identity\nevidence + 1.5 Marks human agency & resistance synthesis):\n• 1. Evidence from Conformity Research [1.5 Marks]:\n- Solomon Asch's experiments demonstrated that social majorities can lead individuals to doubt their own senses and\nconform to consensus.\n• 2. Evidence from Obedience Research [1.5 Marks]:\n- Stanley Milgram's studies showed that ordinary individuals can comply with commands from legitimate authority figures\neven when actions conflict with personal conscience.\n• 3. Evidence from Social Identity Research [1.5 Marks]:\n- Henri Tajfel's work revealed that minimal group categorization triggers ingroup favoritism, demonstrating how social\nidentity shapes group-oriented behavior.\n• 4. Synthesis: Human Agency & Resistance [1.5 Marks]:\n- While social situations exert strong influence, individuals also retain capacities for moral reflection, dissent, and pro-\nsocial action when supported by awareness and ethical commitments.",
